import { parseOpeningHours, type OpeningHoursErrorCode } from "./openingHours";

const closed = { Mo: [], Tu: [], We: [], Th: [], Fr: [], Sa: [], Su: [] };
const r = (from: string, to: string) => ({ from, to });

function expectError(text: string, code: OpeningHoursErrorCode, column: number) {
  let error: unknown;
  try {
    parseOpeningHours(text);
  } catch (e) {
    error = e;
  }
  expect(error).toBeInstanceOf(OpeningHoursError);
  expect({ code: (error as OpeningHoursError).code, column: (error as OpeningHoursError).column }).toEqual({
    code,
    column,
  });
}

test("parses the example", () => {
  const morningAfternoon = [r("08:00", "12:00"), r("13:30", "18:30")];
  expect(parseOpeningHours("Mo-Fr 08:00-12:00,13:30-18:30; Sa 09:00-16:00; Su off")).toEqual({
    Mo: morningAfternoon,
    Tu: morningAfternoon,
    We: morningAfternoon,
    Th: morningAfternoon,
    Fr: morningAfternoon,
    Sa: [r("09:00", "16:00")],
    Su: [],
  });
});

test("days not named are closed", () => {
  expect(parseOpeningHours("We 10:00-11:00")).toEqual({ ...closed, We: [r("10:00", "11:00")] });
});

test("day ranges wrap around and Mo-Mo is one day", () => {
  const h = [r("10:00", "11:00")];
  expect(parseOpeningHours("Fr-Mo 10:00-11:00")).toEqual({ ...closed, Fr: h, Sa: h, Su: h, Mo: h });
  expect(parseOpeningHours("Mo-Mo 10:00-11:00")).toEqual({ ...closed, Mo: h });
});

test("spaces are insignificant", () => {
  const h = [r("08:00", "12:00")];
  expect(parseOpeningHours("Mo,We 08:00 - 12:00")).toEqual({ ...closed, Mo: h, We: h });
  expect(parseOpeningHours("  Mo , We08:00-12:00 ;Tu off  ")).toEqual({ ...closed, Mo: h, We: h });
});

test("ranges are sorted, may touch, and 24:00 ends a range", () => {
  expect(parseOpeningHours("Mo 12:00-24:00,00:00-12:00")).toEqual({
    ...closed,
    Mo: [r("00:00", "12:00"), r("12:00", "24:00")],
  });
});

test("later rules replace earlier ones", () => {
  const all = [r("08:00", "20:00")];
  expect(parseOpeningHours("Mo-Su 08:00-20:00; Su off")).toEqual({
    Mo: all, Tu: all, We: all, Th: all, Fr: all, Sa: all, Su: [],
  });
  const m = [r("08:00", "12:00")];
  expect(parseOpeningHours("Mo-Fr 08:00-12:00; We 14:00-18:00")).toEqual({
    ...closed, Mo: m, Tu: m, We: [r("14:00", "18:00")], Th: m, Fr: m,
  });
});

test("days do not share range objects", () => {
  const result = parseOpeningHours("Mo,Tu 08:00-12:00");
  expect(result.Mo).not.toBe(result.Tu);
  expect(result.Mo[0]).not.toBe(result.Tu[0]);
});

